const cadence=()=>Number($('batch-cadence').value==='custom'?$('custom-cadence').value:$('batch-cadence').value),volume=()=>Number($('batch-volume').value),fmt=t=>`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;
