const selectedOutputs=()=>outputs.filter(o=>o.selected);
const gaps=new Map();
const playlistPreview=createPlaylistPreview({audio:$('playlist-player'),play:$('playlist-play'),seek:$('playlist-seek'),elapsed:$('playlist-elapsed'),total:$('playlist-total'),status:$('playlist-preview-status')});
const timeline=createTimeline({root:$('playlist-timeline'),viewport:$('timeline-viewport'),gaps,
 move:(id,to)=>{if(busy)return;outputs=reorderSelected(outputs,id,to);invalidateMerge();renderOutputs();updateSummary();},
 changeGap:(id,value)=>{if(busy)return;gaps.set(id,value);invalidateMerge();updateSummary();$('timeline-status').textContent=`过渡已设为 ${value} 秒，合并后生效。`;}});
