const playlistDuration=()=>segments().at(-1)?.next||0;
function message(text=''){$('batch-message').textContent=text;$('batch-message').hidden=!text;}
function pauseAll(){document.querySelectorAll('audio').forEach(a=>a.pause());stopTick();}
function stopWorker(){worker?.terminate();worker=null;if(pending){clearTimeout(pending.timer);pending.reject(new Error('已取消'));pending=null;}}
function newWorker(file='audio-worker.js'){stopWorker();worker=new Worker(new URL(file,import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(!pending||data.id!==pending.id)return;if(data.type==='progress'){pending.progress?.(data);return;}const p=pending;pending=null;clearTimeout(p.timer);if(data.type==='error')p.reject(new Error(data.message));else p.resolve(data);};worker.onerror=()=>{if(pending){const p=pending;pending=null;clearTimeout(p.timer);p.reject(new Error('音频组件运行失败，请重试。'));}};}
function request(type,data={},progress){return new Promise((resolve,reject)=>{const id=++sequence,timer=setTimeout(()=>{stopWorker();},240000);pending={id,resolve,reject,progress,timer};const transfer=data.channels?data.channels.map(c=>c.buffer):data.wav?[data.wav]:[];worker.postMessage({type,id,...data},transfer);});}
function setBusy(v){busy=v;for(const el of document.querySelectorAll('#batch-files,#batch-demo,#batch-cadence,#custom-cadence,#batch-volume,.mode-tab'))el.disabled=v;$('batch-progress-area').hidden=!v;render();}
function progress(label,percent){$('batch-progress-text').textContent=label;$('batch-progress').value=percent;}
function revokeOutput(o){o.urls.forEach(URL.revokeObjectURL);}
function invalidateMerge(){if(!$('merged-result').hidden){$('merged-stale').hidden=false;$('merged-player').pause();for(const id of ['merged-mp3','merged-wav']){$(id).style.pointerEvents='none';$(id).style.opacity='.45';$(id).setAttribute('aria-disabled','true');}}}
function clearMerge(){$('merged-player').pause();$('merged-player').removeAttribute('src');$('merged-player').load();mergedUrls.forEach(URL.revokeObjectURL);mergedUrls=[];$('merged-result').hidden=true;}
function element(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function button(text,label,action,disabled=false){const b=element('button','',text);b.setAttribute('aria-label',label);b.disabled=disabled;b.onclick=action;return b;}
function audio(url,label){const a=element('audio');a.controls=true;a.preload='metadata';a.src=url;a.setAttribute('aria-label',label);return a;}
function updateSummary(){const ready=tracks.filter(current).length,chosen=selectedOutputs(),selectedTracks=batchMode?tracks:tracks.filter(t=>t.id===activeSource);$('batch-count').textContent=`${tracks.length} 首`;$('output-count').textContent=`${outputs.length} 首`;$('batch-generate').disabled=busy||!validCadence(cadence())||!selectedTracks.some(t=>Number.isFinite(t.bpm)&&t.bpm>=40&&t.bpm<=260);$('batch-clear').disabled=busy||!tracks.length;$('clear-outputs').disabled=busy||!outputs.length;$('batch-drop').hidden=false;$('batch-drop').classList.toggle('compact',!!tracks.length);$('batch-drop').setAttribute('aria-disabled',String(busy));$('batch-drop').querySelector('b').textContent=busy?'正在处理，完成后可继续拖入':tracks.length?'继续拖入歌曲':'把喜欢的歌曲拖到这里';$('batch-drop').querySelector('small').textContent=tracks.length?'也可直接拖到下方歌曲列表':'自动匹配跑步节奏 · 支持原曲试听';$('output-empty').hidden=!!outputs.length;$('merge-generate').disabled=busy||chosen.length<2;$('merge-duration').textContent=chosen.length?fmt(playlistDuration()):'— : —';$('merge-hint').textContent=chosen.length>=2?`已勾选 ${chosen.length} 首 · 含 ${segments().reduce((s,o)=>s+o.gap,0).toFixed(1)} 秒静音过渡。`:'至少生成并勾选 2 首歌曲后可合并。';$('batch-caption').textContent=tracks.length?`${ready} / ${tracks.length} 首符合当前设置。输出列表中已有的成品不会因切换设置而改变。`:'添加歌曲，让音乐跟上脚步。';timeline.render(chosen,busy);playlistPreview.update(segments());}
function renderInputs(){const list=$('batch-list');list.replaceChildren();tracks.forEach((t,index)=>{
 const row=element('li','queue-item'),main=element('div','queue-main'),title=element('strong','queue-name');row.dataset.id=t.id;title.title=t.name;title.append(element('span','queue-number',String(index+1).padStart(2,'0')),document.createTextNode(t.name));main.append(title);
 const info=element('div','queue-info');if(!batchMode){const pick=element('label','select-merge','制作这首 '),radio=element('input');radio.type='radio';radio.name='source-choice';radio.checked=t.id===activeSource;radio.disabled=busy;radio.setAttribute('aria-label',`制作这首：${t.name}`);radio.onchange=()=>{activeSource=t.id;updateSummary();};pick.prepend(radio);info.append(pick);}info.append(element('span','',fmt(t.duration)));
 info.append(element('span','queue-status'+(t.error?' error':''),t.error||(current(t)?'✓ 已生成':t.status||'准备中')));main.append(info);
 const adjustment=element('details','tempo-adjustment');adjustment.open=!!t.calibrationOpen||!!t.error;adjustment.ontoggle=()=>{t.calibrationOpen=adjustment.open;};adjustment.append(element('summary','','调整音乐速度'));
 const help=element('p','',!current(t)&&outputs.some(o=>o.id===t.id)?'设置已更新，请重新生成并试听右侧成品，再进行下一次调整。':current(t)?'试听右侧成品。如果人声明显过快或过慢，选择下面的调整，再重新生成。点声仍保持你选择的步频。':'通常直接生成即可。先试听右侧成品，觉得音乐速度不合适时，再用下面的按钮调整。');adjustment.append(help);
 const options=element('div','tempo-options');
 for(const [direction,text] of [['slower','成品太快了，放慢音乐'],['faster','成品太慢了，加快音乐']]){const next=adjustedTempo(t.bpm,direction);options.append(button(text,`${text}：${t.name}`,()=>{t.bpm=next;t.error='';t.status='速度已调整，请重新生成';t.calibrationOpen=true;render();},busy||!current(t)||next===null));}
 if(t.analysis)options.append(button('恢复自动推荐',`恢复自动推荐：${t.name}`,()=>{t.bpm=suggestedTempo(t.analysis.bpm);t.error='';t.status='已恢复自动推荐';t.calibrationOpen=true;render();},busy));adjustment.append(options);
 const label=element('label','manual-tempo','高级：原曲 BPM（一般无需修改） '),input=element('input');input.type='number';input.min='40';input.max='260';input.step='.01';input.value=Number.isFinite(t.bpm)?t.bpm.toFixed(2):'';input.disabled=busy;input.setAttribute('aria-label',`原曲 BPM：${t.name}`);input.onchange=()=>{const value=Number(input.value);t.bpm=Number.isFinite(value)&&value>=40&&value<=260?value:null;t.error='';t.status=t.bpm?'已调整，请重新生成':'请输入 40–260 BPM';t.calibrationOpen=true;render();};label.append(input);adjustment.append(label);main.append(adjustment);
 main.append(audio(t.url,`输入试听：${t.name}`));const tools=element('div','queue-tools');tools.append(button('×',`移除输入：${t.name}`,()=>{URL.revokeObjectURL(t.url);tracks=tracks.filter(x=>x.id!==t.id);if(activeSource===t.id)activeSource=tracks[0]?.id||null;render();},busy));row.append(main,tools);list.append(row);
 });}
function renderOutputs(){const list=$('output-list');list.replaceChildren();outputs.forEach((o,index)=>{
 const row=element('li','queue-item output-item');row.dataset.id=o.id;const handle=button('⋮⋮',`拖动输出排序：${o.name}`,()=>{},busy);handle.className='drag-handle';handle.onpointerdown=e=>startDrag(e,o.id);handle.onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();moveOutput(o.id,index+(e.key==='ArrowUp'?-1:1));}};
 const main=element('div','queue-main'),title=element('strong','queue-name');title.title=o.name;title.append(element('span','queue-number',String(index+1).padStart(2,'0')),document.createTextNode(o.name));main.append(title);const info=element('div','queue-info');info.append(element('span','output-bpm',`${o.target} 步频`),element('span','',`${fmt(o.duration)} · 点声 ${o.volume}%`));const select=element('label','select-merge','合并'),check=element('input');check.type='checkbox';check.checked=o.selected;check.disabled=busy;check.setAttribute('aria-label',`合并选择：${o.name}`);check.onchange=()=>{o.selected=check.checked;invalidateMerge();updateSummary();};select.prepend(check);info.append(select);main.append(info,audio(o.urls[0],`输出试听：${o.name}`));const links=element('div','queue-downloads');for(const [kind,url] of [['mp3',o.urls[0]],['wav',o.urls[1]]]){const a=element('a','',`↓ ${kind.toUpperCase()}`);a.href=url;attachDownload(a,o.files[kind],`${o.baseName}.${kind}`);links.append(a);}main.append(links);
 const tools=element('div','queue-tools output-tools');tools.append(button('↑',`上移输出：${o.name}`,()=>moveOutput(o.id,index-1),busy||index===0),button('↓',`下移输出：${o.name}`,()=>moveOutput(o.id,index+1),busy||index===outputs.length-1),button('×',`移除输出：${o.name}`,()=>{revokeOutput(o);outputs=outputs.filter(x=>x.id!==o.id);invalidateMerge();render();},busy));row.append(handle,main,tools);list.append(row);
 });}
function render(){renderInputs();renderOutputs();updateSummary();}
function moveOutput(id,to){if(busy||to<0||to>=outputs.length)return;const from=outputs.findIndex(t=>t.id===id);if(from===to||from<0)return;const [item]=outputs.splice(from,1);outputs.splice(to,0,item);invalidateMerge();renderOutputs();updateSummary();}
function startDrag(event,id){if(busy||event.button!==0)return;event.preventDefault();const handle=event.currentTarget,row=handle.closest('.output-item');handle.setPointerCapture(event.pointerId);row.classList.add('dragging');let over=null,after=false;
 const moving=e=>{const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.output-item');document.querySelectorAll('.drop-before').forEach(r=>r.classList.remove('drop-before'));if(target&&target.dataset.id!==id){over=target.dataset.id;after=e.clientY>target.getBoundingClientRect().top+target.getBoundingClientRect().height/2;target.classList.add('drop-before');}if(e.clientY<70)window.scrollBy(0,-14);if(e.clientY>innerHeight-70)window.scrollBy(0,14);};
 const end=e=>{handle.removeEventListener('pointermove',moving);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',cancel);try{handle.releasePointerCapture(e.pointerId);}catch{}if(over){const item=outputs.find(t=>t.id===id);outputs=outputs.filter(t=>t.id!==id);const index=outputs.findIndex(t=>t.id===over);outputs.splice(index+(after?1:0),0,item);invalidateMerge();}renderOutputs();updateSummary();};
 const cancel=e=>{over=null;end(e);};handle.addEventListener('pointermove',moving);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',cancel);
}
async function decode(file){const b=await context().decodeAudioData(await file.arrayBuffer());if(b.duration<8||b.duration>480)throw new Error('单首时长需为 8 秒至 8 分钟。');return b;}
function channels(b){return [b.getChannelData(0).slice(),b.getChannelData(Math.min(1,b.numberOfChannels-1)).slice()];}
async function addFiles(files){if(busy)return;let input=Array.from(files);if(!batchMode)input=input.slice(0,1);if(!input.length)return;message();const run=++epoch;setBusy(true);newWorker();let errors=[];try{for(const file of input){if(run!==epoch)break;if(tracks.length>=12){errors.push('最多添加 12 首歌曲。');break;}if(file.size>80*1048576){errors.push(`${file.name}：超过 80 MB。`);continue;}if(tracks.some(t=>t.name===file.name&&t.file.size===file.size&&t.file.lastModified===file.lastModified)){errors.push(`${file.name}：已在输入列表中。`);continue;}let t;try{progress(`正在读取 ${file.name}`,0);const decoded=await decode(file);if(run!==epoch)break;if(tracks.reduce((s,x)=>s+x.duration,0)+decoded.duration>2400)throw new Error('总时长不能超过 40 分钟。');t={id:crypto.randomUUID(),file,name:file.name,url:URL.createObjectURL(file),duration:decoded.duration,bpm:null,status:'正在识别',error:''};tracks.push(t);activeSource=t.id;activeItem=t;render();const data=await request('load',{channels:channels(decoded),sampleRate:sr},p=>progress(`识别第 ${tracks.length} 首 · ${Math.round(p.value)}%`,p.value));if(run!==epoch)break;t.analysis=data.analysis;t.bpm=suggestedTempo(data.analysis.bpm);t.status=data.analysis.stable?'已自动匹配跑步节奏':'已自动匹配，请先试听成品';render();}catch(error){if(run!==epoch)break;if(t){t.error='识别未完成，请手动输入 BPM';t.status='';}errors.push(`${file.name}：${error.message}`);render();}}}finally{if(run===epoch){activeItem=null;stopWorker();setBusy(false);message(errors.join('　'));}}}
async function generateAll(){if(busy)return;if(!validCadence(cadence())){message('目标步频请输入 160–210 之间的整数。');return;}message();pauseAll();const run=++epoch;setBusy(true);newWorker();const target=cadence(),vol=volume(),chosen=batchMode?[...tracks]:tracks.filter(t=>t.id===activeSource);let failed=0;try{for(let i=0;i<chosen.length;i++){const t=chosen[i];if(run!==epoch)break;if(current(t))continue;if(!t.bpm){t.error='请先输入原曲 BPM';failed++;continue;}activeItem=t;t.error='';t.status='正在处理';render();try{const b=await decode(t.file);if(run!==epoch)break;await request('load',{channels:channels(b),sampleRate:sr},p=>progress(`${i+1}/${chosen.length} · 正在读取节拍`,(i+p.value/100*.15)/chosen.length*100));if(run!==epoch)break;const data=await request('generate',{target,sourceBpm:t.bpm,volume:vol},p=>progress(`${i+1}/${chosen.length} · ${p.label} ${Math.round(p.value)}%`,(i+.15+p.value/100*.85)/chosen.length*100));if(run!==epoch)break;const files={mp3:new Blob([data.mp3],{type:'audio/mpeg'}),wav:new Blob([data.wav],{type:'audio/wav'})},oldIndex=outputs.findIndex(o=>o.id===t.id),baseName=`${t.name.replace(/\.[^.]+$/,'')} - ${target}步频 点声${vol}%`,out={color:oldIndex>=0?outputs[oldIndex].color:outputs.length%4,id:t.id,name:t.name,target,volume:vol,bpm:t.bpm,duration:data.duration,files,baseName,selected:oldIndex>=0?outputs[oldIndex].selected:true,urls:[URL.createObjectURL(files.mp3),URL.createObjectURL(files.wav)]};if(oldIndex>=0){revokeOutput(outputs[oldIndex]);outputs[oldIndex]=out;}else outputs.push(out);t.status=`✓ 已完成`;invalidateMerge();render();await autoSave(files,baseName);}catch(error){if(run!==epoch)break;t.error=error.message;t.status='';failed++;render();}}}finally{if(run===epoch){activeItem=null;stopWorker();setBusy(false);message(failed?`${failed} 首未完成，成功的音频已保留在输出列表。`:'生成完成。右侧可试听、下载，勾选并调整顺序后可合并。');}}}
async function mergeAll(){const ordered=selectedOutputs(),transitions=segments().slice(0,-1).map(s=>s.gap),totalDuration=playlistDuration();if(busy||ordered.length<2)return;const run=++epoch;message();pauseAll();setBusy(true);newWorker('merge-worker.js');try{progress('准备合并音频',0);const wav=await joinWavBlobs(ordered.map(o=>o.files.wav),transitions);await request('start');for(let i=0;i<ordered.length;i++){if(run!==epoch)return;const bytes=await ordered[i].files.wav.arrayBuffer();if(run!==epoch)return;await request('track',{wav:bytes,gapBefore:i?transitions[i-1]:0},p=>progress(`正在合并 ${i+1}/${ordered.length} · ${ordered[i].name}`,(i+p.value)/ordered.length*100));}const data=await request('finish');if(run!==epoch)return;clearMerge();const files={mp3:new Blob([data.mp3],{type:'audio/mpeg'}),wav},mp3Url=URL.createObjectURL(files.mp3),wavUrl=URL.createObjectURL(files.wav);mergedUrls=[mp3Url,wavUrl];const tempos=[...new Set(ordered.map(o=>o.target))],pace=tempos.length===1?`${tempos[0]}步频`:'混合步频',baseName=`踏频跑步歌单 - ${pace} - ${ordered.length}首`;$('merged-player').src=mp3Url;for(const [id,url,kind] of [['merged-mp3',mp3Url,'mp3'],['merged-wav',wavUrl,'wav']]){$(id).href=url;attachDownload($(id),files[kind],`${baseName}.${kind}`);$(id).style.pointerEvents='';$(id).style.opacity='';$(id).removeAttribute('aria-disabled');}$('merged-meta').textContent=`${ordered.length} 首 · ${fmt(totalDuration)} · ${pace}`;$('merged-stale').hidden=true;$('merged-result').hidden=false;await autoSave(files,baseName);message('合并完成，已按时间轴顺序加入静音过渡。');}catch(error){if(run===epoch)message('合并未完成：'+error.message);}finally{if(run===epoch){stopWorker();setBusy(false);}}}
for(const mode of ['single','batch'])$(mode+'-tab').onclick=()=>{if(busy)return;batchMode=mode==='batch';for(const other of ['single','batch']){$(other+'-tab').classList.toggle('active',other===mode);$(other+'-tab').setAttribute('aria-pressed',String(other===mode));}$('batch-files').multiple=batchMode;$('generate-label').textContent=batchMode?'一键批量生成':'生成选中单曲';$('mode-hint').textContent=batchMode?'可一次选择多首':'一次添加一首';$('batch-demo').textContent=batchMode?'试用 2 首示例':'试用示例';render();};
$('batch-files').onchange=e=>{addFiles(e.target.files);e.target.value='';};
setupFileDrop(document.querySelector('.input-panel'),{isBusy:()=>busy,onFiles:addFiles,onMessage:message});
function updateCadence(){const custom=$('batch-cadence').value==='custom',valid=validCadence(cadence());$('custom-cadence-wrap').hidden=!custom;$('cadence-error').hidden=!custom||valid;$('custom-cadence').setAttribute('aria-invalid',String(!valid));$('hero-bpm').textContent=valid?cadence():'—';$('preview-tick').disabled=!valid;stopTick();updateSummary();}
$('batch-cadence').onchange=updateCadence;$('custom-cadence').oninput=updateCadence;$('batch-volume').oninput=()=>{$('batch-volume-value').textContent=volume()+'%';stopTick();updateSummary();};
$('batch-generate').onclick=generateAll;$('merge-generate').onclick=mergeAll;
$('batch-cancel').onclick=()=>{epoch++;stopWorker();if(activeItem){activeItem.status='已取消，可重试';activeItem.error='';}activeItem=null;setBusy(false);message('已取消当前操作，输出列表中已完成的单曲仍保留。');};
$('batch-clear').onclick=()=>{if(busy)return;tracks.forEach(t=>URL.revokeObjectURL(t.url));tracks=[];activeSource=null;message('已清空输入，已生成的输出仍保留。');render();};
$('clear-outputs').onclick=()=>{if(busy)return;outputs.forEach(revokeOutput);outputs=[];gaps.clear();clearMerge();render();message('已清空页面输出列表，已保存到电脑的文件不受影响。');};
$('batch-demo').onclick=()=>{if(busy)return;const first=demoAudio(sr),second=first.map(c=>c.slice(0,sr*12));addFiles([new File([encodeWav(first,sr)],'晨跑出发 · 示例一.wav',{type:'audio/wav',lastModified:1}),new File([encodeWav(second,sr)],'轻快前进 · 示例二.wav',{type:'audio/wav',lastModified:2})]);};
function stopTick(){clearTimeout(tickTimer);tickNodes.forEach(n=>{try{n.stop();}catch{}});tickNodes=[];$('preview-tick').textContent='▷ 试听点声';}
$('preview-tick').onclick=async()=>{if(tickNodes.length){stopTick();return;}try{pauseAll();const c=context();await c.resume();const samples=tickSamples(sr),b=c.createBuffer(1,samples.length,sr);b.copyToChannel(samples,0);for(let i=0;i<8;i++){const src=c.createBufferSource(),gain=c.createGain();src.buffer=b;gain.gain.value=clickPreviewGain(volume());src.connect(gain).connect(c.destination);src.start(c.currentTime+.06+i*60/cadence());tickNodes.push(src);}$('preview-tick').textContent='■ 停止试听';tickTimer=setTimeout(stopTick,(.15+8*60/cadence())*1000);}catch{message('浏览器未能播放点声，请确认允许音频播放。');}};
document.addEventListener('play',event=>{if(event.target.tagName==='AUDIO'){document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause();});stopTick();}},true);
window.addEventListener('pagehide',()=>{playlistPreview.dispose();stopWorker();tracks.forEach(t=>URL.revokeObjectURL(t.url));outputs.forEach(revokeOutput);mergedUrls.forEach(URL.revokeObjectURL);ctx?.close();});setupOutputFolder();render();
